[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.2.0/fonts/remixicon.css" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --primary: #0066FF;
      --primary-dark: #0052CC;
      --accent: #00B894;
      --accent-dark: #009B7D;
      --navy: #1B1464;
      --yellow: #FFD930;
      --white: #FFFFFF;
      --gray-50: #F8FAFC;
      --gray-100: #F1F5F9;
      --gray-200: #E2E8F0;
      --gray-300: #CBD5E1;
      --gray-500: #64748B;
      --gray-700: #334155;
      --gray-900: #0F172A;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--gray-900);
      line-height: 1.6;
      background: var(--white);
      overflow-x: hidden;
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    img {
      max-width: 100%;
      display: block;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: var(--white);
      z-index: 1000;
      box-shadow: var(--shadow-sm);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 24px;
      font-weight: 800;
      color: var(--primary);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--primary);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 20px;
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-links {
      display: flex;
      gap: 32px;
      list-style: none;
    }

    .nav-links a {
      font-weight: 500;
      color: var(--gray-700);
      transition: color 0.2s;
    }

    .nav-links a:hover {
      color: var(--primary);
    }

    .nav-buttons {
      display: flex;
      gap: 12px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 10px 20px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 14px;
      cursor: pointer;
      border: none;
      transition: all 0.2s;
    }

    .btn-ghost {
      background: transparent;
      color: var(--gray-700);
    }

    .btn-ghost:hover {
      background: var(--gray-100);
    }

    .btn-primary {
      background: var(--primary);
      color: white;
    }

    .btn-primary:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-accent {
      background: var(--accent);
      color: white;
    }

    .btn-accent:hover {
      background: var(--accent-dark);
    }

    .btn-large {
      padding: 14px 28px;
      font-size: 16px;
    }

    .mobile-toggle {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      font-size: 24px;
      color: var(--gray-700);
    }

    /* Mobile Menu */
    .mobile-menu {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 999;
      padding: 24px;
      flex-direction: column;
      gap: 24px;
      animation: slideIn 0.3s ease;
    }

    .mobile-menu.active {
      display: flex;
    }

    @keyframes slideIn {
      from { opacity: 0; transform: translateY(-10px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .mobile-menu a {
      font-size: 18px;
      font-weight: 500;
      padding: 16px 0;
      border-bottom: 1px solid var(--gray-200);
    }

    .mobile-menu-buttons {
      display: flex;
      flex-direction: column;
      gap: 12px;
      margin-top: auto;
    }

    /* Hero Section */
    .hero {
      padding: 160px 24px 80px;
      background: linear-gradient(135deg, var(--gray-50) 0%, var(--white) 100%);
      text-align: center;
      min-height: 600px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }

    .hero h1 {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 16px;
      line-height: 1.1;
      max-width: 800px;
    }

    .hero p {
      font-size: 18px;
      color: var(--gray-500);
      max-width: 640px;
      margin-bottom: 40px;
      line-height: 1.7;
    }

    /* Search Bar */
    .search-container {
      width: 100%;
      max-width: 960px;
      background: var(--white);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-xl);
      padding: 8px;
      margin-top: 20px;
    }

    .search-form {
      display: grid;
      grid-template-columns: 2fr 1.5fr 1.5fr auto;
      gap: 8px;
      align-items: center;
    }

    .search-field {
      position: relative;
    }

    .search-field i {
      position: absolute;
      left: 16px;
      top: 50%;
      transform: translateY(-50%);
      color: var(--gray-500);
      font-size: 18px;
    }

    .search-input {
      width: 100%;
      padding: 14px 14px 14px 48px;
      border: 2px solid transparent;
      border-radius: var(--radius);
      font-size: 16px;
      background: var(--gray-50);
      transition: all 0.2s;
      font-family: inherit;
    }

    .search-input:focus {
      outline: none;
      border-color: var(--primary);
      background: var(--white);
      box-shadow: 0 0 0 4px rgba(0, 102, 255, 0.1);
    }

    .search-input::placeholder {
      color: var(--gray-500);
    }

    .search-btn {
      padding: 14px 32px;
      background: var(--primary);
      color: white;
      border: none;
      border-radius: var(--radius);
      font-size: 16px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .search-btn:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    /* Autocomplete Dropdown */
    .autocomplete {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      right: 0;
      background: var(--white);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--gray-200);
      z-index: 100;
      display: none;
      max-height: 300px;
      overflow-y: auto;
    }

    .autocomplete.active {
      display: block;
    }

    .autocomplete-item {
      padding: 12px 16px;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 12px;
      transition: background 0.15s;
    }

    .autocomplete-item:hover {
      background: var(--gray-50);
    }

    .autocomplete-item i {
      color: var(--primary);
      font-size: 18px;
    }

    /* Specialties Section */
    .specialties {
      padding: 80px 24px;
      background: var(--white);
    }

    .section-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: 36px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 12px;
    }

    .section-header p {
      color: var(--gray-500);
      font-size: 18px;
    }

    .specialty-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 24px;
    }

    .specialty-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 32px 24px;
      text-align: center;
      cursor: pointer;
      transition: all 0.3s;
      border: 2px solid transparent;
    }

    .specialty-card:hover {
      background: var(--white);
      border-color: var(--primary);
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .specialty-icon {
      width: 64px;
      height: 64px;
      background: var(--white);
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
      font-size: 28px;
      color: var(--primary);
      box-shadow: var(--shadow-sm);
    }

    .specialty-card h3 {
      font-size: 16px;
      font-weight: 600;
      color: var(--navy);
      margin-bottom: 8px;
    }

    .specialty-card p {
      font-size: 13px;
      color: var(--gray-500);
      line-height: 1.5;
    }

    /* How It Works */
    .how-it-works {
      padding: 80px 24px;
      background: var(--gray-50);
    }

    .steps {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 48px;
      margin-top: 48px;
    }

    .step {
      text-align: center;
      position: relative;
    }

    .step-number {
      width: 56px;
      height: 56px;
      background: var(--primary);
      color: white;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      font-weight: 700;
      margin: 0 auto 24px;
    }

    .step h3 {
      font-size: 20px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 12px;
    }

    .step p {
      color: var(--gray-500);
      line-height: 1.6;
    }

    .step::after {
      content: '';
      position: absolute;
      top: 28px;
      right: -24px;
      width: 48px;
      height: 2px;
      background: var(--gray-300);
    }

    .step:last-child::after {
      display: none;
    }

    /* Stats Section */
    .stats {
      padding: 60px 24px;
      background: var(--primary);
      color: white;
    }

    .stats-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }

    .stat {
      text-align: center;
    }

    .stat-value {
      font-size: 42px;
      font-weight: 800;
      margin-bottom: 8px;
      color: var(--yellow);
    }

    .stat-label {
      font-size: 16px;
      opacity: 0.9;
    }

    /* Testimonials */
    .testimonials {
      padding: 80px 24px;
      background: var(--white);
    }

    .testimonial-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      margin-top: 48px;
    }

    .testimonial-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      padding: 32px;
      position: relative;
    }

    .testimonial-card::before {
      content: '"';
      font-size: 80px;
      color: var(--primary);
      opacity: 0.2;
      position: absolute;
      top: 16px;
      left: 24px;
      line-height: 1;
    }

    .testimonial-text {
      font-size: 16px;
      line-height: 1.7;
      color: var(--gray-700);
      margin-bottom: 24px;
      position: relative;
      z-index: 1;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .author-avatar {
      width: 48px;
      height: 48px;
      background: var(--primary);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-weight: 700;
      font-size: 18px;
    }

    .author-info strong {
      display: block;
      font-size: 15px;
      color: var(--navy);
    }

    .author-info span {
      font-size: 13px;
      color: var(--gray-500);
    }

    /* Mobile App Promo */
    .app-promo {
      padding: 80px 24px;
      background: var(--navy);
      color: white;
      position: relative;
      overflow: hidden;
    }

    .app-promo::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(0, 102, 255, 0.3) 0%, transparent 70%);
      border-radius: 50%;
    }

    .app-promo-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
      position: relative;
      z-index: 1;
    }

    .app-content h2 {
      font-size: 36px;
      font-weight: 800;
      margin-bottom: 16px;
    }

    .app-content p {
      font-size: 18px;
      opacity: 0.8;
      margin-bottom: 32px;
      line-height: 1.7;
    }

    .app-buttons {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .store-btn {
      display: flex;
      align-items: center;
      gap: 12px;
      background: var(--white);
      color: var(--navy);
      padding: 14px 24px;
      border-radius: var(--radius);
      font-weight: 600;
      transition: transform 0.2s;
    }

    .store-btn:hover {
      transform: scale(1.02);
    }

    .store-btn i {
      font-size: 28px;
    }

    .store-btn-text {
      text-align: left;
      line-height: 1.3;
    }

    .store-btn-text span {
      display: block;
      font-size: 11px;
      font-weight: 500;
    }

    .app-features {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
    }

    .app-feature {
      display: flex;
      align-items: flex-start;
      gap: 16px;
    }

    .app-feature i {
      font-size: 24px;
      color: var(--accent);
    }

    .app-feature span {
      font-size: 15px;
      opacity: 0.9;
    }

    /* Footer */
    .footer {
      background: var(--gray-900);
      color: var(--gray-300);
      padding: 64px 24px 32px;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(4, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand {
      max-width: 280px;
    }

    .footer-brand .logo {
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-brand p {
      font-size: 14px;
      line-height: 1.7;
      margin-bottom: 24px;
    }

    .footer-col h4 {
      color: var(--white);
      font-size: 14px;
      font-weight: 600;
      margin-bottom: 16px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .footer-col ul {
      list-style: none;
    }

    .footer-col li {
      margin-bottom: 12px;
    }

    .footer-col a {
      font-size: 14px;
      transition: color 0.2s;
    }

    .footer-col a:hover {
      color: var(--white);
    }

    .footer-bottom {
      padding-top: 32px;
      border-top: 1px solid var(--gray-700);
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-bottom p {
      font-size: 13px;
    }

    .footer-legal {
      display: flex;
      gap: 24px;
    }

    .footer-legal a {
      font-size: 13px;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .search-form {
        grid-template-columns: 1fr 1fr;
      }

      .search-btn {
        grid-column: span 2;
      }

      .testimonial-grid,
      .steps {
        grid-template-columns: 1fr;
      }

      .step::after {
        display: none;
      }

      .stats-inner {
        grid-template-columns: repeat(2, 1fr);
      }

      .app-promo-inner {
        grid-template-columns: 1fr;
        text-align: center;
      }

      .app-buttons {
        justify-content: center;
      }

      .app-features {
        max-width: 400px;
        margin: 0 auto;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .nav-links,
      .nav-buttons {
        display: none;
      }

      .mobile-toggle {
        display: block;
      }

      .hero {
        padding: 120px 16px 60px;
      }

      .search-form {
        grid-template-columns: 1fr;
      }

      .search-btn {
        grid-column: auto;
      }

      .specialty-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .stats-inner {
        grid-template-columns: 1fr 1fr;
        gap: 24px;
      }

      .stat-value {
        font-size: 32px;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }

      .footer-bottom {
        flex-direction: column;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
      .specialty-grid {
        grid-template-columns: 1fr;
      }

      .app-buttons {
        flex-direction: column;
      }

      .store-btn {
        justify-content: center;
      }
    }
  </style>
</head>
<body>
  <!-- Header -->
  <header class="header">
    <div class="header-inner">
      <a href="#" class="logo">
        <div class="logo-icon"><i class="ri-heart-line"></i></div>
        MedBook
      </a>
      <nav class="nav">
        <ul class="nav-links">
          <li><a href="#">Browse</a></li>
          <li><a href="#">Help</a></li>
        </ul>
        <div class="nav-buttons">
          <button class="btn btn-ghost">Log In</button>
          <button class="btn btn-primary">Sign Up</button>
        </div>
      </nav>
      <button class="mobile-toggle" id="mobileToggle" aria-label="Toggle menu">
        <i class="ri-menu-line"></i>
      </button>
    </div>
  </header>

  <!-- Mobile Menu -->
  <div class="mobile-menu" id="mobileMenu">
    <a href="#">Browse</a>
    <a href="#">Help</a>
    <a href="#">Log In</a>
    <a href="#">Sign Up</a>
    <div class="mobile-menu-buttons">
      <button class="btn btn-primary btn-large" style="width: 100%;">Sign Up</button>
    </div>
  </div>

  <!-- Hero Section -->
  <section class="hero">
    <h1>Find and book the care you need</h1>
    <p>Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.</p>

    <!-- Search Bar -->
    <div class="search-container">
      <form class="search-form" id="searchForm">
        <div class="search-field">
          <i class="ri-search-line"></i>
          <input type="text" class="search-input" id="specialtyInput" placeholder="Search by condition, specialty, or doctor name" autocomplete="off">
          <div class="autocomplete" id="specialtyAutocomplete">
            <div class="autocomplete-item" data-value="Primary Care"><i class="ri-user-line"></i>Primary Care</div>
            <div class="autocomplete-item" data-value="Dentist"><i class="ri-women-line"></i>Dentist</div>
            <div class="autocomplete-item" data-value="Dermatologist"><i class="ri-hand-heart-line"></i>Dermatologist</div>
            <div class="autocomplete-item" data-value="Psychiatrist"><i class="ri-brain-line"></i>Psychiatrist</div>
            <div class="autocomplete-item" data-value="Eye Doctor"><i class="ri-eye-line"></i>Eye Doctor</div>
            <div class="autocomplete-item" data-value="Orthopedic Surgeon"><i class="ri-leg-line"></i>Orthopedic Surgeon</div>
            <div class="autocomplete-item" data-value="Back pain"><i class="ri-first-aid-kit-line"></i>Back pain</div>
            <div class="autocomplete-item" data-value="Dr. Sarah Chen"><i class="ri-vip-diamond-line"></i>Dr. Sarah Chen</div>
          </div>
        </div>
        <div class="search-field">
          <i class="ri-map-pin-line"></i>
          <input type="text" class="search-input" placeholder="City, state, or zip code">
        </div>
        <div class="search-field">
          <i class="ri-shield-line"></i>
          <select class="search-input" style="cursor: pointer;">
            <option value="">Choose your insurance plan</option>
            <option value="aetna">Aetna</option>
            <option value="bcbs">Blue Cross Blue Shield</option>
            <option value="cigna">Cigna</option>
            <option value="united">UnitedHealthcare</option>
            <option value="humana">Humana</option>
            <option value="cigna">Kaiser Permanente</option>
          </select>
        </div>
        <button type="submit" class="search-btn">
          <i class="ri-search-line"></i>
          Search
        </button>
      </form>
    </div>
  </section>

  <!-- Specialties Section -->
  <section class="specialties">
    <div class="section-inner">
      <div class="section-header">
        <h2>Popular Specialties</h2>
        <p>Find the right provider for your needs</p>
      </div>
