  <script>
    // Mobile menu toggle
    const mobileToggle = document.getElementById('mobileToggle');
    const mobileMenu = document.getElementById('mobileMenu');

    mobileToggle.addEventListener('click', () => {
      mobileMenu.classList.toggle('active');
      const icon = mobileToggle.querySelector('i');
      icon.classList.toggle('ri-menu-line');
      icon.classList.toggle('ri-close-line');
    });

    // Autocomplete functionality
    const specialtyInput = document.getElementById('specialtyInput');
    const autocomplete = document.getElementById('specialtyAutocomplete');
    const autocompleteItems = autocomplete.querySelectorAll('.autocomplete-item');

    specialtyInput.addEventListener('input', () => {
      const query = specialtyInput.value.toLowerCase();
      if (query.length > 0) {
        autocomplete.classList.add('active');
        autocompleteItems.forEach(item => {
          const value = item.dataset.value.toLowerCase();
          item.style.display = value.includes(query) ? 'flex' : 'none';
        });
      } else {
        autocomplete.classList.remove('active');
      }
    });

    specialtyInput.addEventListener('blur', () => {
      setTimeout(() => {
        autocomplete.classList.remove('active');
      }, 200);
    });

    autocompleteItems.forEach(item => {
      item.addEventListener('click', () => {
        specialtyInput.value = item.dataset.value;
        autocomplete.classList.remove('active');
      });
    });

    // Search form submission
    const searchForm = document.getElementById('searchForm');
    searchForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const query = specialtyInput.value || 'doctors';
      alert(`Searching for "${query}"... This would navigate to search results in a full implementation.`);
    });

    // Specialty card navigation
    document.querySelectorAll('.specialty-card').forEach(card => {
      card.addEventListener('click', (e) => {
        e.preventDefault();
        const specialty = card.querySelector('h3').textContent;
        alert(`Navigating to ${specialty} search results... This would navigate to a filtered search page in a full implementation.`);
      });
    });
  </script>
